FILES = json.loads(zlib.decompress(base64.b64decode("".join(DATA.split()))).decode())
ROOT = next((os.path.abspath(c) for c in (sys.argv[1] if len(sys.argv) > 1 else None, os.path.dirname(os.path.abspath(__file__)), os.getcwd(), r"C:\EmergencyResponseSystem")
             if c and os.path.isdir(os.path.join(c, "functions")) and os.path.isdir(os.path.join(c, "mobile"))), None)
if not ROOT:
    sys.exit("STOP: run this from C:\\EmergencyResponseSystem (the folder that contains functions and mobile).")
for need in ("mobile/lib/core/ui/tokens.dart", "mobile/lib/core/ui/glass.dart", "mobile/lib/features/resident/map/help_map_screen.dart"):
    if not os.path.exists(os.path.join(ROOT, *need.split("/"))):
        sys.exit("STOP: " + need + " is missing. Run install_phase4a.py first, then run this again.")
BK = os.path.join(ROOT, "backup_before_phase4b")
for rel, text in FILES.items():
    path = os.path.join(ROOT, *rel.split("/"))
    if os.path.exists(path):
        if open(path, encoding="utf-8").read() == text:
            print("  skipped  :", rel, "(already installed)"); continue
        bk = os.path.join(BK, *rel.split("/"))
        if not os.path.exists(bk):
            os.makedirs(os.path.dirname(bk), exist_ok=True); shutil.copy2(path, bk)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    open(path, "w", encoding="utf-8", newline="\n").write(text)
    print("  installed:", rel)
print("INSTALL OK")
